options.onLazyLoad:
const { level, value, childrenData } = node
if(!!childrenData) {
  resolve(childrenData)
  return
}
const idOrPath = level == 0 ? "/" : value
$api.post('/admin/api/dms/document/children/thumbnail', {idOrPath, pageSize: 100000}).then(res => {
  const nodes = res.data.data.entryList.reduce((prev, item) => { 
    if(item.isFolder) prev.push({
      value: item.id,
      label: item.name
    })
    return prev
  },[])
  const list = nodes.sort((a,b) => a.label.localeCompare(b.label))
  // 通过调用resolve将子节点数据返回，通知组件数据加载完成
  resolve(list)
}).catch(err => {
  resolve([])
})

options.onMounted:
init()
const _this = this
async function init () {
  const groupList = await getGroupList()
  const userList = await getUserList()
  const list = [
    { label: $i18n.t('user_groups'), options: groupList },
    { label: $i18n.t('user_users'), options: userList },
    { value: 'user_roles', label: $i18n.t('user_roles'), options: await roleListFilter() },
  ]
  _this.loadOptions(list)
  // 
}
async function getGroupList () {
  try {
    const data = await $api.get('/groups/select', { baseURL: '/gateway' }).then(res => res.data.data)
    const result = data.reduce((prev,item) => {
      if (item.value) {
        prev.push({
          value: `group&&&&${item.value}`,
          label: item.label
        })
      }
      return prev
    }, [])
    return result.sort((a,b)=> (a.label.localeCompare(b.label) ))
  } catch (e) {
    return[]
  }
}
async function getUserList () {
  try {
    const data = await $api.get('/users/select', { baseURL: '/gateway' }).then(res => res.data.data)
    const result =  data.reduce((prev,item) => {
      if(item.value) {
        prev.push({
          value: `user&&&&${item.value}`,
          label: item.label
        })
      }
      return prev
    }, [])
    return result.sort((a,b)=> (a.label.localeCompare(b.label) ))
  } catch (e) {
    return[]
  }
}
async function roleListFilter () {
  try {
    const data = await $api.get('/api/docpal/acl/role/root').then((res) => res.data.data)
    const roleList = data ? makeFlapRoleList([data]) : []
    return roleList.map((item) => ({
      label: item.name,
      value: 'role&&&&' + item.id
    }))
  } catch (error) {
    console.error(error)
    return []
  }
}
function makeFlapRoleList(data, roleList = []) {
  data.forEach((node) => {
    const _node = { ...node }
    delete _node.children
    roleList.push(_node)
    if (node.children) {
      makeFlapRoleList(node.children, roleList)
    }
  })
  return roleList
}
